// SmartHelmet/Software/src/pages/Dashboard.jsx

import { useState, useEffect, useRef } from 'react';
import Sidebar from '../components/Sidebar';
import Header from '../components/Header';
import SurveillanceTunnelMap from '../components/SurveillanceTunnelMap';
import WorkerStatusCard from '../components/WorkerStatusCard';
import SensorCard from '../components/SensorCard';
import AlertsCard from '../components/AlertsCard';
import SensorTrendsCard from '../components/SensorTrendsCard';
import LiveDebugPanel from '../components/LiveDebugPanel';
import useLiveData from '../hooks/useLiveData';
import { getRSSIZone } from '../services/api';
import { THRESHOLDS } from '../utils/constants';

const HISTORY_LIMIT = 20;

/**
 * Derive per-sensor status from the current reading using known thresholds.
 */
function getSensorStatus(reading, field) {
  if (!reading || reading[field] === null || reading[field] === undefined) return 'normal';
  const val = reading[field];

  if (field === 'temperature') {
    if (val >= THRESHOLDS.temperature.emergency) return 'emergency';
    if (val >= THRESHOLDS.temperature.warning) return 'warning';
    return 'normal';
  }
  if (field === 'gas_level') {
    if (val >= THRESHOLDS.gas_level.emergency) return 'emergency';
    if (val >= THRESHOLDS.gas_level.warning) return 'warning';
    return 'normal';
  }
  if (field === 'force') {
    if (val >= THRESHOLDS.force.emergency) return 'emergency';
    if (val >= THRESHOLDS.force.warning) return 'warning';
    return 'normal';
  }
  if (field === 'heart_rate') {
    if (val > 0 && (val <= THRESHOLDS.heart_rate.emergencyLow || val >= THRESHOLDS.heart_rate.emergencyHigh)) return 'emergency';
    if (val > 0 && (val <= THRESHOLDS.heart_rate.warningLow || val >= THRESHOLDS.heart_rate.warningHigh)) return 'warning';
    return 'normal';
  }
  return 'normal';
}

import { GradientWave } from '../components/ui/GradientWave';

export default function Dashboard() {
  const { reading, alerts, worker, status, loading } = useLiveData();

  // ── Rolling history of recent readings ────────────────
  const [history, setHistory] = useState([]);
  const seenIdsRef = useRef(new Set());

  useEffect(() => {
    if (!reading) return;

    // Deduplicate using id or created_at
    const key = reading.id || reading.created_at;
    if (key && seenIdsRef.current.has(key)) return;

    if (key) seenIdsRef.current.add(key);

    setHistory((prev) => {
      const updated = [...prev, reading];
      // Keep only the latest HISTORY_LIMIT entries
      if (updated.length > HISTORY_LIMIT) {
        const trimmed = updated.slice(updated.length - HISTORY_LIMIT);
        // Also trim the seen set to avoid unbounded growth
        const validKeys = new Set(
          trimmed.map((r) => r.id || r.created_at).filter(Boolean)
        );
        seenIdsRef.current = validKeys;
        return trimmed;
      }
      return updated;
    });
  }, [reading]);

  // ── Derive current zone from RSSI ─────────────────────
  const currentZone = getRSSIZone(reading?.rssi);

  return (
    <div className="min-h-screen" style={{ position: 'relative', background: '#060B26' }}>
      {/* ── Custom Animated WebGL Background ───────────── */}
      <div
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          zIndex: 0,
          pointerEvents: 'none',
          opacity: 0.6,
        }}
      >
        <GradientWave
          colors={["#060B26", "#0F123B", "#090D2E", "#00d4ff", "#020515", "#0F123B"]}
          isPlaying={true}
          noiseSpeed={0.00001}
          shadowPower={6}
          deform={{ incline: 0.2, noiseAmp: 150, noiseFlow: 1.5, noiseSpeed: 5 }}
        />
      </div>

      <Sidebar />
      <Header />

      {/* ── Main content area ─────────────────────── */}
      <main
        style={{
          marginLeft: 'var(--sidebar-width)',
          marginTop: 'var(--header-height)',
          minHeight: 'calc(100vh - var(--header-height))',
          padding: '24px 24px 24px 40px',
          position: 'relative',
          zIndex: 1,
        }}
      >
        {/* ── Row 0: Surveillance Tunnel Map (TOP) ── */}
        <div style={{ marginBottom: 24 }}>
          <SurveillanceTunnelMap
            worker={worker}
            reading={reading}
            zone={currentZone}
            status={status}
          />
        </div>

        {/* ── Row 1: Worker Status ─────────────────── */}
        <div style={{ marginBottom: 24 }}>
          <WorkerStatusCard worker={worker} status={status} reading={reading} />
        </div>

        {/* ── Row 2: Sensor Cards Grid ─────────────── */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
            gap: 20,
            marginBottom: 24,
          }}
        >
          <SensorCard
            label="Temperature"
            value={reading?.temperature}
            unit="°C"
            status={getSensorStatus(reading, 'temperature')}
            icon="🌡️"
            subtitle="Ambient mine temperature"
          />
          <SensorCard
            label="Gas Level"
            value={reading?.gas_level}
            unit="ppm"
            status={getSensorStatus(reading, 'gas_level')}
            icon="💨"
            subtitle="MQ-series gas concentration"
          />
          <SensorCard
            label="Force"
            value={reading?.force}
            unit="N"
            status={getSensorStatus(reading, 'force')}
            icon="⚡"
            subtitle="Helmet impact force"
          />
          <SensorCard
            label="Heart Rate"
            value={reading?.heart_rate}
            unit="bpm"
            status={getSensorStatus(reading, 'heart_rate')}
            icon="❤️"
            subtitle="Worker pulse rate"
          />
          <SensorCard
            label="SpO2"
            value={reading?.spo2}
            unit="%"
            status="normal"
            icon="🫁"
            subtitle="Blood oxygen saturation"
          />
          <SensorCard
            label="RSSI"
            value={reading?.rssi}
            unit="dBm"
            status="normal"
            icon="📡"
            subtitle="Beacon signal strength"
          />
        </div>

        {/* ── Row 3: Alerts + Sensor Trends ─────────── */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(2, 1fr)',
            gap: 20,
            marginBottom: 24,
          }}
          className="alerts-trends-row"
        >
          <AlertsCard alerts={alerts} />
          <SensorTrendsCard history={history} />
        </div>

        {/* ── Debug Panel (de-emphasized) ──────────── */}
        <div style={{ opacity: 0.6, marginTop: 32 }}>
          <LiveDebugPanel
            reading={reading}
            alerts={alerts}
            worker={worker}
            status={status}
            loading={loading}
          />
        </div>
      </main>

      {/* Inline responsive override */}
      <style>{`
        @media (max-width: 900px) {
          .alerts-trends-row {
            grid-template-columns: 1fr !important;
          }
        }
      `}</style>
    </div>
  );
}
